 {"name":"pattern_set_cell","arguments":{"pattern":10,"row":24,"channel":8,"note":"==="}},
 {"name":"pattern_set_cell","arguments":{"pattern":10,"row":24,"channel":9,"note":"==="}},
 {"name":"pattern_set_cell","arguments":{"pattern":10,"row":32,"channel":4,"note":"==="}},
]
def build(chs, out):
    files = {1:'kick',2:'snare',3:'hatc',4:'hato',5:'clap',6:'bass',7:'sub',
             8:'saw',9:'arp',10:'pad',11:'pluck',12:'tick',13:'fx'}
    vols  = {1:64,2:58,3:46,4:42,5:52,6:64,7:64,8:54,9:46,10:48,11:58,12:40,13:50}
