    for c in pat:
        if c['name']=='pattern_set_cell' and c['arguments']['pattern']==10 and c['arguments']['channel'] in chs:
            used.add(c['arguments'].get('instrument'))
    for c in extra:
        if c['arguments']['channel'] in chs: calls.append(c)
    for i in sorted({u for u in used if u}):
        calls.insert(1,{"name":"sample_load","arguments":{"path":f"/workspace/samples/{files[i]}.wav","instrument":i,"sample":0}})
