        if i in loops: meta.update({"loop_start":loops[i][0],"loop_length":loops[i][1],"flags":17})
        calls.insert(2,{"name":"sample_set","arguments":meta})
    calls.append({"name":"pattern_set_length","arguments":{"pattern":10,"rows":64}})
    for c in pat:
        if c['name']=='pattern_set_cell' and c['arguments']['pattern']==10 and c['arguments']['channel'] in chs:
            calls.append(c)
    calls += [{"name":"order_set","arguments":{"position":0,"pattern":10}},
              {"name":"song_set","arguments":{"bpm":132,"speed":6,"length":1}},
              {"name":"module_render","arguments":{"path":out,"rate":44100}}]
    json.dump(calls, open('scripts/px.json','w'))
    subprocess.run(['ft2','batch','scripts/px.json'], capture_output=True)
    w = wave.open(out,'rb'); sr=w.getframerate()
    d = np.frombuffer(w.readframes(w.getnframes()), dtype='<i2').astype(np.float64)
